/* 1. Box-sizing chuẩn */
*, *::before, *::after {
  box-sizing: border-box;
}

/* 2. Xóa margin mặc định để tự quản lý dễ hơn */
* {
  margin: 0;
  padding: 0;
}

/* 3. Chiều cao dòng chuẩn, mượt mà */
body {
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

/* 4. Hình ảnh dễ làm responsive hơn */
img, picture, video, canvas, svg {
  display: block;
  max-width: 100%;
}

/* 5. Khôi phục font-family cho form element */
input, button, textarea, select {
  font: inherit;
  outline: none;
}

/* 6. Xóa list style */
ul, ol {
  list-style: none;
}

/* Block: Component độc lập */
.card {
  padding: 16px;
  border: 1px solid #ddd;
  border-radius: 8px;
}

/* Element: Luôn bắt đầu bằng tên Block + __ */
.card__title {
  font-size: 1.2rem;
  margin-bottom: 8px;
}
.card__text {
  color: #666;
  margin-bottom: 12px;
}

/* Modifier: Trạng thái hoặc biến thể của Block/Element + -- */
.btn {
  padding: 8px 16px;
  border-radius: 4px;
  border: none;
  cursor: pointer;
}
.btn--primary {
  background: blue;
  color: white;
}
.btn--outline {
  background: transparent;
  border: 1px solid blue;
  color: blue;
}
.btn--disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

/* 1. Spacing (Khoảng cách) */
.mt-1 { margin-top: 4px; }
.mt-2 { margin-top: 8px; }
.mt-3 { margin-top: 16px; }
.mt-4 { margin-top: 24px; }
.mb-3 { margin-bottom: 16px; }
.gap-2 { gap: 8px; }

/* 2. Text (Chữ) */
.text-center { text-align: center; }
.text-right { text-align: right; }
.text-primary { color: #007bff; }
.font-bold { font-weight: bold; }

/* 3. Layout */
.flex { display: flex; }
.flex-center { justify-content: center; align-items: center; }
.w-100 { width: 100%; }
.d-none { display: none; }

/* 4. Responsive Utility */
@media (min-width: 768px) {
  .md-block { display: block; }
}

/* 1. ĐỊNH NGHĨA HỆ THỐNG Z-INDEX */
:root {
  --z-negative: -1;
  --z-elevate: 10;
  --z-sticky: 100;
  --z-dropdown: 200;
  --z-offcanvas: 300;
  --z-modal: 400;
  --z-popover: 500;
  --z-tooltip: 600;
}

/* 2. SỬ DỤNG */
.header {
  position: sticky; top: 0;
  z-index: var(--z-sticky);
  background: #6c5ce7; color: white; padding: 10px;
}

.dropdown {
  position: absolute; top: 30px; left: 10px;
  z-index: var(--z-dropdown);
  background: white; border: 1px solid black;
  padding: 10px;
}

.modal {
  position: fixed; top: 50%; left: 50%; transform: translate(-50%, -50%);
  z-index: var(--z-modal);
  background: #ff7675; color: white; padding: 20px;
  box-shadow: 0 10px 30px rgba(0,0,0,0.5);
}

.scroll-container {
  height: 150px;
  overflow-y: auto;
  border: 1px solid #ddd;
  padding: 10px;
  background: #f8f9fa;

  /* Chuẩn Firefox */
  scrollbar-width: thin;
  scrollbar-color: #a29bfe transparent;
}

/* Chuẩn Webkit (Chrome, Edge, Safari) */
/* 1. Độ rộng toàn thanh cuộn */
.scroll-container::-webkit-scrollbar {
  width: 6px; /* Nhỏ gọn, thanh lịch */
  height: 6px; /* Cho cuộn ngang */
}

/* 2. Track (phần nền) */
.scroll-container::-webkit-scrollbar-track {
  background: transparent;
  border-radius: 4px;
}

/* 3. Thumb (nút cầm kéo) */
.scroll-container::-webkit-scrollbar-thumb {
  background: #a29bfe;
  border-radius: 4px;
}

/* 4. Hover Thumb */
.scroll-container::-webkit-scrollbar-thumb:hover {
  background: #6c5ce7;
}

.real-btn {
  padding: 10px 20px;
  background: #0984e3;
  color: white;
  border: none;
  border-radius: 6px;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.2s ease;
}

/* 1. Trạng thái rê chuột */
.real-btn:hover:not(:disabled) {
  background: #74b9ff;
  transform: translateY(-2px);
  box-shadow: 0 4px 12px rgba(9, 132, 227, 0.3);
}

/* 2. Trạng thái nhấn chuột xuống (:active) */
.real-btn:active:not(:disabled), .active-demo {
  transform: translateY(0);
  box-shadow: none;
  background: #076aba;
}

/* 3. Focus từ bàn phím (Tab) */
.real-btn:focus-visible {
  outline: 2px solid #fdcb6e;
  outline-offset: 2px;
}

/* 4. Vô hiệu hóa (thuộc tính disabled) */
.real-btn:disabled {
  background: #b2bec3;
  color: #636e72;
  cursor: not-allowed;
  opacity: 0.7;
}

.ratio-container {
  display: flex;
  gap: 20px;
  align-items: flex-start;
}

.ratio-box {
  width: 150px; /* Chỉ cần set Width, Height sẽ tự tính! */
  background: #00b894;
  color: white;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: bold;
  font-size: 11px;
  text-align: center;
  border-radius: 8px;
  object-fit: cover; /* Hữu ích nếu là thẻ img */
}

/* Tỷ lệ Video YouTube */
.video-ratio {
  aspect-ratio: 16 / 9;
}

/* Tỷ lệ vuông */
.square-ratio {
  aspect-ratio: 1 / 1;
}
